import {listTools,callTool} from "./server.mjs";

const eq = (a,b)=>JSON.stringify(a)===JSON.stringify(b);

// omitted note -> null
console.log("omitted:", eq(JSON.parse((await callTool("user_note",{user_id:"u1"})).content[0].text).note, null));

// null note -> null
console.log("null:", eq(JSON.parse((await callTool("user_note",{user_id:"u1",note:null})).content[0].text).note, null));

// string note -> string
console.log("string:", eq(JSON.parse((await callTool("user_note",{user_id:"u1",note:"hi"})).content[0].text).note, "hi"));

// returns user_id
console.log("user_id:", eq(JSON.parse((await callTool("user_note",{user_id:"u1",note:"hi"})).content[0].text).user_id, "u1"));

// non-string non-null note rejected
try{ await callTool("user_note",{user_id:"u1",note:5}); console.log("number note: NOT rejected (bad)"); }
catch(e){ console.log("number note rejected:", e.message); }

try{ await callTool("user_note",{user_id:"u1",note:false}); console.log("bool note: NOT rejected (bad)"); }
catch(e){ console.log("bool note rejected:", e.message); }

// missing user_id rejected
try{ await callTool("user_note",{}); console.log("missing user_id: NOT rejected (bad)"); }
catch(e){ console.log("missing user_id rejected:", e.message); }

// extra field rejected? (protocol enforces schema; callTool with extra)
try{ await callTool("user_note",{user_id:"u1",extra:"x"}); console.log("extra field: NOT rejected by callTool (schema-level)"); }
catch(e){ console.log("extra field rejected:", e.message); }

// unknown tool rejected
try{ await callTool("bogus",{}); console.log("unknown tool: NOT rejected (bad)"); }
catch(e){ console.log("unknown tool rejected:", e.message); }

// schema checks
const [t] = await listTools();
console.log("additionalProperties false:", t.inputSchema.additionalProperties === false);
console.log("required user_id:", JSON.stringify(t.inputSchema.required)===JSON.stringify(["user_id"]));
console.log("note nullable via anyOf:", !!t.inputSchema.properties.note.anyOf);
console.log("note anyOf has null:", t.inputSchema.properties.note.anyOf.some(s=>s.type==="null"));
console.log("note anyOf has string:", t.inputSchema.properties.note.anyOf.some(s=>s.type==="string"));
' --input-type=module 2>&1"}

